contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 shares, address owner) public {
        // call with owner different from caller: must revert
        bool revertedWrongOwner;
        address caller = address(this);
        if (owner != caller) {
            try c.requestRedeem(shares, owner) { revertedWrongOwner = false; }
            catch { revertedWrongOwner = true; }
            assert(revertedWrongOwner);
        }
        // call with owner equal to caller: must pass the approval check
        bool revertedSelf;
        try c.requestRedeem(shares, caller) { revertedSelf = false; }
        catch { revertedSelf = true; }
        assert(!revertedSelf);
    }
    receive() external payable {}
}

