    constructor(C _c) { c = _c; }
    function run(uint128 price) public {
        // Caller (this contract) is a ward from deployment; set a known price.
        c.updatePrice(price);
        // Revoke our own authorization.
        c.deny(address(this));
        // While denied, updatePrice must revert and leave latestPrice unchanged.
        bool reverted;
        try c.updatePrice(price + 1) { reverted = false; } catch { reverted = true; }
        // Re-grant authorization.
